namespace sv_1c024c8aafb342bd931489cc2f0d1fcb.Services;

/// <summary>
/// Scoped service that holds the current warehouse selection for a single circuit (user session).
/// Each SignalR circuit gets its own instance, so multiple managers see independent state.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-001", "Warehouse A — Downtown"),
        ("WH-002", "Warehouse B — Airport"),
        ("WH-003", "Warehouse C — Harbor"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            OnChanged?.Invoke();
        }
    }

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId).Name
        ?? _currentWarehouseId;

    /// <summary>Fired whenever the selected warehouse changes.</summary>
    public event Action? OnChanged;

    public void Dispose() => OnChanged = null;
}

namespace sv_1c024c8aafb342bd931489cc2f0d1fcb.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and broadcasts changes
/// to all subscribed components within the same circuit.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private static readonly Random s_random = Random.Shared;

    private int _lastCount;

    public int LastCount => _lastCount;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = s_random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches fresh data and notifies all subscribers if the value changed (or force-notify on warehouse switch).
    /// </summary>
    public async Task RefreshAsync(string warehouseId, bool forceNotify = false)
    {
        var count = await GetLowStockCountAsync(warehouseId);
        var changed = count != _lastCount || forceNotify;
        _lastCount = count;
        if (changed)
        {
            OnAlertCountChanged?.Invoke(count);
        }
    }

    /// <summary>Fired when the alert count changes. All subscribed components receive this.</summary>
    public event Action<int>? OnAlertCountChanged;

    public void Dispose() => OnAlertCountChanged = null;
}

@rendermode InteractiveServer
@using sv_1c024c8aafb342bd931489cc2f0d1fcb.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label class="form-label mb-0 text-nowrap fw-semibold" for="warehouseSelect">
        🏭 Site:
    </label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="max-width: 260px;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChanged += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "";
    }

    public void Dispose()
    {
        WarehouseState.OnChanged -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@using sv_1c024c8aafb342bd931489cc2f0d1fcb.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (_count > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto" title="@_count low-stock items">@_count</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto" title="No low-stock items">0</span>
}

@code {
    private int _count;

    protected override void OnInitialized()
    {
        _count = AlertService.LastCount;
        AlertService.OnAlertCountChanged += OnCountChanged;
    }

    private void OnCountChanged(int newCount)
    {
        _count = newCount;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnCountChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_1c024c8aafb342bd931489cc2f0d1fcb.Services
@using sv_1c024c8aafb342bd931489cc2f0d1fcb.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>📊 Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-5">
            <strong>@WarehouseState.CurrentWarehouseName</strong>
            <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title d-flex align-items-center gap-2">
            ⚠️ Low-Stock Alerts
            <AlertBadge />
        </h5>
        <p class="card-text">
            There are currently <strong>@_alertCount</strong> items below minimum stock levels
            at @WarehouseState.CurrentWarehouseName.
        </p>
        <p class="text-muted small mb-0">
            Auto-refreshes every 10 seconds. Last checked: @_lastChecked.ToString("HH:mm:ss")
        </p>
    </div>
</div>

<div class="card">
    <div class="card-body">
        <h5 class="card-title">Polling Status</h5>
        <span class="badge @(_polling ? "bg-success" : "bg-secondary")">
            @(_polling ? "● Active" : "○ Inactive")
        </span>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastChecked = DateTime.Now;
    private bool _polling;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.LastCount;
        WarehouseState.OnChanged += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling when the dashboard becomes visible
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId, forceNotify: true);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _polling = true;
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _polling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async void OnWarehouseChanged()
    {
        // Warehouse switched — restart polling with fresh data immediately
        StartPolling();
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId, forceNotify: true);
        await InvokeAsync(StateHasChanged);
    }

    private void OnAlertCountChanged(int newCount)
    {
        _alertCount = newCount;
        _lastChecked = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChanged -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

