@using sv_1c024c8aafb342bd931489cc2f0d1fcb.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label class="form-label mb-0 text-nowrap fw-semibold" for="warehouseSelect">
        🏭 Site:
    </label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="max-width: 260px;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChanged += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "";
    }

    public void Dispose()
    {
        WarehouseState.OnChanged -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@using sv_1c024c8aafb342bd931489cc2f0d1fcb.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (_count > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto" title="@_count low-stock items">@_count</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto" title="No low-stock items">0</span>
}

@code {
    private int _count;

    protected override void OnInitialized()
    {
        _count = AlertService.LastCount;
        AlertService.OnAlertCountChanged += OnCountChanged;
    }

    private void OnCountChanged(int newCount)
    {
        _count = newCount;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnCountChanged;
    }
}

