toolArgs.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@using sv_1c024c8aafb342bd931489cc2f0d1fcb.Services
@using sv_1c024c8aafb342bd931489cc2f0d1fcb.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard — @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>📊 Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-5">
            <strong>@WarehouseState.CurrentWarehouseName</strong>
            <span class="text-muted">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title d-flex align-items-center gap-2">
            ⚠️ Low-Stock Alerts
            <AlertBadge />
        </h5>
        <p class="card-text">
            There are currently <strong>@_alertCount</strong> items below minimum stock levels
            at @WarehouseState.CurrentWarehouseName.
        </p>
        <p class="text-muted small mb-0">
            Auto-refreshes every 10 seconds. Last checked: @_lastChecked.ToString("HH:mm:ss")
        </p>
    </div>
</div>

<div class="card">
    <div class="card-body">
        <h5 class="card-title">Polling Status</h5>
        <span class="badge @(_polling ? "bg-success" : "bg-secondary")">
            @(_polling ? "● Active" : "○ Inactive")
        </span>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastChecked = DateTime.Now;
    private bool _polling;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.LastCount;
        WarehouseState.OnChanged += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling when the dashboard becomes visible
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId, forceNotify: true);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _polling = true;
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private void StopPolling()
    {
        _polling = false;
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async void OnWarehouseChanged()
    {
        // Warehouse switched — restart polling with fresh data immediately
        StartPolling();
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId, forceNotify: true);
        await InvokeAsync(StateHasChanged);
    }

    private void OnAlertCountChanged(int newCount)
    {
        _alertCount = newCount;
        _lastChecked = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChanged -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
    }
}

